2711	// ── CONTIGUOUS-TRANSPOSE PASS (SG_TUNED_DEC_DW_STAGE=1). Grid-cooperatively
2712	//    transpose each weight's dY[K,Nout] → dYt[Nout,K] and X[K,Kin] → Xt[Kin,K]
2713	//    into the packed dW-T scratch the specs bind. ELEMENT-OWNED (one writer per
2714	//    output element, fixed mapping) → DETERMINISTIC and A/A/A-safe; PURE bf16
2715	//    COPY (dYt[m,k]=dY[k,m] — NO arithmetic, NO reduction) → fp64-oracle parity
2716	//    is trivially preserved (the wgmma later consumes the SAME bf16 operand
2717	//    values in the SAME ascending-k order; only their MEMORY LAYOUT changed from
2718	//    transposed-strided gmem to K-contiguous gmem). Called by ALL CTAs after the
2719	//    backward writes dY/X to acts and BEFORE the dW phase, fenced by the existing
2720	//    B1 grid barrier (no new barrier). The total work is Σ_s (Nout_s+Kin_s)·K_s
2721	//    bf16 stores, touched ONCE per step and reused across every dW work item +
2722	//    split-K chunk of that weight. ──
2723	__device__ __forceinline__ void dectc_dw_transpose_operands(
2724	        const DecDwSpec spec[kDecNumDwSpecs], int cta, int nCTA) {
2725	#if SG_TUNED_DEC_DW_STAGE
2726	    if constexpr (!kDecDwTransposeActive) { (void)spec; (void)cta; (void)nCTA; return; }
2727	    const int tpb = blockDim.x;
2728	    const int64_t stride = (int64_t)nCTA * tpb;
2729	    const int64_t lane0  = (int64_t)cta * tpb + threadIdx.x;
2730	    for (int s = 0; s < kDecNumDwSpecs; ++s) {
2731	        const DecDwSpec& sp = spec[s];
2732	        if (sp.dYt == nullptr) continue;
2733	        const int64_t K = sp.K, Nout = sp.Nout, Kin = sp.Kin;
2734	        const int64_t Mpad = dec_dw_mpad(sp.Nout);
2735	        // dYt[m,k] = dY[k,m] for m<Nout; pad rows [Nout,Mpad) = 0 (inert — the
2736	        // ring reads A rows unguarded, so the row dim is padded to a 64-atom
2737	        // boundary). Linear out-index i = m*K+k over the FULL padded [Mpad,K).
2738	        const int64_t ndy = Mpad * K;
2739	        for (int64_t i = lane0; i < ndy; i += stride) {
2740	            const int64_t m = i / K, k = i % K;
2741	            sp.dYt[i] = (m < Nout) ? sp.dY[k * Nout + m] : __float2bfloat16(0.f);
2742	        }
2743	        // Xt[n,k] = X[k,n], n in [0,Kin), k in [0,K). Linear out-index i = n*K+k.
2744	        // (No row pad: the ring guards B rows via row_valid → pad N-tile cols are
2745	        // zero-filled in smem, never read from Xt.)
2746	        const int64_t nx = Kin * K;
2747	        for (int64_t i = lane0; i < nx; i += stride) {
2748	            const int64_t n = i / K, k = i % K;
2749	            sp.Xt[i] = sp.X[k * Kin + n];
2750	        }
2751	    }
2752	#else
2753	    (void)spec; (void)cta; (void)nCTA;   // scalar default: no transpose pass
2754	#endif
2755	}
