2757	// ── dW M-atom INTERLEAVE group width (task #13 H3). A dW output "tile" (work
2758	//    item) owns a GROUP of up to kDecDwIL consecutive m64 atoms instead of one,
2759	//    so the engine runs kDecDwIL wgmmas/k-step into independent fragments sharing
2760	//    ONE staged X (B-operand) tile → the H1 win (overlap the MMAs + kDecDwIL× less
2761	//    X-operand HBM traffic) now applies to the dW K=T contraction (the post-H2
2762	//    dominant phase). kDecDwIL == the engine's interleave cap kDecMaxIL so the
2763	//    ring smem (DecTcSmem.sA, sized kDecAtomsPerSlot=min(kAtomsM,kDecMaxIL) A-tiles
2764	//    per slot) and the selftest-validated dW path (gemm_dw_kernel: MaxAtomsM=8,
2765	//    kIL=min(8,2)=2) match exactly. Ascending-k per atom is unchanged → numerics
2766	//    bit-identical + A/A/A determinism. Atoms-per-weight-N-tile / groups: ──
2767	constexpr int kDecDwIL = kDecMaxIL;
2768	__device__ __host__ __forceinline__ int dec_dw_atoms(int Nout)  { return (Nout + 63) / 64; }
2769	__device__ __host__ __forceinline__ int dec_dw_groups(int Nout) {
2770	    return (dec_dw_atoms(Nout) + kDecDwIL - 1) / kDecDwIL;
2771	}
