2773	// Total number of dW output WORK ITEMS (M-atom groups × N-tiles) across the 9
2774	// weights (the tile loop count). Each item is a group of <= kDecDwIL m64 atoms.
2775	template <int N>
2776	__device__ __forceinline__ int dectc_dw_total_tiles(const DecDwSpec spec[kDecNumDwSpecs]) {
2777	    int n = 0;
2778	    for (int s = 0; s < kDecNumDwSpecs; ++s)
2779	        n += dec_dw_groups(spec[s].Nout) * ((spec[s].Kin + N - 1) / N);
2780	    return n;
2781	}
