2783	// Run ONE global dW work item `gt` (if it belongs to this CTA): decode (weight,
2784	// M-atom GROUP, N-tile), then contract K via the dW GEMM into grad[grad_off]. The
2785	// group is up to kDecDwIL stacked m64 atoms → the engine interleaves them (kIL=
2786	// kDecDwIL): kDecDwIL wgmmas/k-step into independent fragments sharing ONE staged
2787	// X B-tile (H1's win, now on the dW K=T contraction).
2788	template <int N>
2789	__device__ __forceinline__ void dectc_dw_run_tile(
2790	        const DecDwSpec spec[kDecNumDwSpecs], int gt, float* __restrict__ grad,
2791	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
2792	    // Decode gt → (s, m_group, n_tile).
2793	    int acc = 0, s = 0, m_group = 0, n_tile = 0;
2794	    for (s = 0; s < kDecNumDwSpecs; ++s) {
2795	        const int ng = dec_dw_groups(spec[s].Nout);
2796	        const int nt = (spec[s].Kin + N - 1) / N;
2797	        if (gt < acc + ng * nt) { int loc = gt - acc; m_group = loc / nt; n_tile = loc % nt; break; }
2798	        acc += ng * nt;
2799	    }
2800	    const DecDwSpec& sp = spec[s];
2801	    const int n_atoms = dec_dw_atoms(sp.Nout);
2802	    const int a0 = m_group * kDecDwIL;               // first atom of the group
2803	    const int g_atoms = (n_atoms - a0) < kDecDwIL ? (n_atoms - a0) : kDecDwIL;
2804	    const int mbase = a0 * 64;
2805	    const int n0 = n_tile * N;
2806	    const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
2807	    const int k_steps = sp.K / wgs::kWgmmaAtomK;     // K = T or B (must be /16; padded by caller)
2808	    const int Nout = sp.Nout, Kin = sp.Kin;
2809	    // out(m,n,v): m is GLOBAL (engine adds mbase0=mbase); identical on both paths.
2810	    auto out  = [&] (int m, int n, float v) {
2811	        if (m < Nout) grad[sp.grad_off + (int64_t)m * Kin + n0 + n] = v; };
2812	    // ── SCALAR transposed-strided gather (DEFAULT path; lambda sources). The
2813	    //    engine (tc_gemm_block_unpipelined, mbase0=mbase) passes the GLOBAL row
2814	    //    m = mbase + (group-local row) to srcA/out (it adds mbase0 itself), so the
2815	    //    accessors use `m` RAW (the selftest gemm_dw_kernel passes mbase0=0 + m
2816	    //    raw; we shard atoms into groups, pass mbase0=mbase, likewise m raw).
2817	    //    A[m=out,k=t]=dY[t,out], B[n=in,k=t]=X[t,in] — both TRANSPOSED-strided.
2818	    //    Lambda sources ⇒ DecTileSrcIsGmem=false ⇒ the engine's kRingAsync gate is
2819	    //    OFF ⇒ the synchronous 2-byte LDG→reg→STS stage_kmajor_tile. ──
2820	    auto run_scalar = [&] {
2821	        const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
2822	        auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
2823	            return m < Nout ? dY[(int64_t)k * Nout + m] : __float2bfloat16(0.f); };
2824	        auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
2825	            int nn = n0 + n; return nn < Kin ? X[(int64_t)k * Kin + nn] : __float2bfloat16(0.f); };
2826	        tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/kDecDwIL>(
2827	            mbase, g_atoms, n_real, k_steps, srcA, srcB, out, sA, sB);
2828	    };
2829	#if SG_TUNED_DEC_DW_STAGE
2830	    if constexpr (kDecDwTransposeActive) {
2831	        // DEFENSIVE: a caller that did NOT run dectc_dw_transpose_operands (e.g.
2832	        // the PP-stage / SAM dW phases, which build specs via the 4-arg overload →
2833	        // dYt/Xt null) falls back to the scalar gather rather than dereferencing a
2834	        // null transpose scratch. The wired proof path (fused_decoder_megakernel_tc)
2835	        // always populates dYt/Xt first, so it takes the fast contiguous branch.
2836	        if (sp.dYt == nullptr || sp.Xt == nullptr) { run_scalar(); return; }
2837	        // ── CONTIGUOUS-LAYOUT path: the operands were PRE-TRANSPOSED into K-major
2838	        //    gmem (dYt[Mpad,K], Xt[Kin,K]) by dectc_dw_transpose_operands, so the
2839	        //    A/B rows are now K-CONTIGUOUS + 16B-aligned. Feeding the engine the
2840	        //    flat-gmem DecGmemTileSrc{A,B} (the SAME POD sources the fwd/dX
2841	        //    wrappers use) FLIPS DecTileSrcIsGmem to true → the engine's proven
2842	        //    cp.async ring (kRingAsync) streams them in 16-byte coalesced copies
2843	        //    instead of stage_kmajor_tile's 2-byte transposed-strided gather. The
2844	        //    wgmma issue sequence + ascending-k accumulation are UNCHANGED (the
2845	        //    same A[m,k]=dY[k,m] / B[n,k]=X[k,n] operand values reach the MMA in
2846	        //    the same order) → bit-identical to the scalar path. A's row dim is
2847	        //    padded to Mpad (64-atom boundary) so the ring's UNGUARDED A reads
2848	        //    stay in-bounds; B uses rows_valid=Kin-n0 (the ring zero-fills pad
2849	        //    N-cols). ld = K (the transposed row stride in elements).
2850	        const int K = (int)sp.K;
2851	        DecGmemTileSrcA srcA{sp.dYt, K};                       // A[m,k] = dYt[m·K + k]
2852	        DecGmemTileSrcB srcB{sp.Xt + (int64_t)n0 * K, K, Kin - n0};  // B[n,k] = Xt[(n0+n)·K + k]
2853	        tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/kDecDwIL>(
2854	            mbase, g_atoms, n_real, k_steps, srcA, srcB, out, sA, sB);
2855	    } else {
2856	        // stage==1 but split-K active → the _splitk path handles the dW; this
2857	        // single-CTA wrapper keeps the scalar gather (consistent + unused).
2858	        run_scalar();
2859	    }
2860	#else
2861	    run_scalar();
2862	#endif
2863	}
