2865	// ════════════════════════════════════════════════════════════════════════
2866	//  SPLIT-K dW (multi-CTA tiling — the validated mamba fix). The 9 dW yield only
2867	//  ~50 output tiles → ~62% of 132 SMs idle in P2. Split-K turns each output tile
2868	//  into G work items (one per K-chunk), so the grid sees (n_dw·G) items → idle
2869	//  SMs do work. Each CTA computes a PARTIAL over its K-chunk into a per-(tile,
2870	//  chunk) scratch slot; a grid barrier; then a DETERMINISTIC ascending-chunk
2871	//  reduce sums the G partials into grad — no float atomics, fixed order, so
2872	//  parity + A/A/A bit-determinism hold (each partial is the SAME ascending-k fp32
2873	//  wgmma accumulate; Σ_chunk == full-K sum reassociated into G fp32 blocks).
2874	//  G==1 routes to the single-CTA dectc_dw_run_tile above (no scratch). Slot (gt,
2875	//  kc) at dw_part[((gt*G+kc)) * (kDecDwIL·64·kDecMaxTileN) + lr*kDecMaxTileN + col]
2876	//  — each work item gt is an M-atom GROUP (up to kDecDwIL=2 stacked m64 atoms, H3),
2877	//  so its slot holds kDecDwIL·64 group-local rows (lr). Decoder K varies per spec:
2878	//  layer dW K=T, head dW K=B (so kc_steps reads sp.K).
2879	// ════════════════════════════════════════════════════════════════════════
2880	constexpr int kDecMaxTileN = SG_TUNED_TILE_N;                       // widest dW N-tile
2881	// Floats per (gt,kc) split-K slot: a work item is an M-atom GROUP of up to kDecDwIL
2882	// stacked m64 atoms → kDecDwIL·64 rows × N cols. (Was 64·N for the 1-atom item.)
2883	constexpr int kDecDwTileFloats = kDecDwIL * wgs::kWgmmaAtomM * kDecMaxTileN;
2884	
2885	// COMPILE-TIME max #dW output WORK ITEMS (the 9 dW have fixed Nout/Kin; decoder
2886	// dims are compile-time → constant). per layer: qkv(3d×d), attn_out(d×d), ff0(dff
2887	// ×d), ff2(d×dff), N=kDecMaxTileN; + head(V×d). The M factor is now M-atom GROUPS
2888	// of kDecDwIL (ceil(atoms/kDecDwIL)), matching dec_dw_groups — NOT single atoms.
2889	constexpr int kDecDwMGroups(int Nout) {                 // ceil(ceil(Nout/64)/kDecDwIL)
2890	    return (((Nout + 63) / 64) + kDecDwIL - 1) / kDecDwIL;
2891	}
2892	constexpr int kDecDwTilesPerLayer =
2893	      kDecDwMGroups(3*dec::kD) * ((dec::kD  + kDecMaxTileN - 1)/kDecMaxTileN)   // qkv
2894	    + kDecDwMGroups(dec::kD)   * ((dec::kD  + kDecMaxTileN - 1)/kDecMaxTileN)   // attn_out
2895	    + kDecDwMGroups(dec::kDff) * ((dec::kD  + kDecMaxTileN - 1)/kDecMaxTileN)   // ff0
2896	    + kDecDwMGroups(dec::kD)   * ((dec::kDff+ kDecMaxTileN - 1)/kDecMaxTileN);  // ff2
2897	constexpr int kDecDwHeadTiles =
2898	      kDecDwMGroups(dec::kVocab) * ((dec::kD + kDecMaxTileN - 1)/kDecMaxTileN);
2899	constexpr int kDecDwMaxTiles = dec::kLayers * kDecDwTilesPerLayer + kDecDwHeadTiles;
2900	
2901	// Split-K dW partial-scratch float count (host carves it from the workspace tail).
2902	__host__ __device__ __forceinline__ int64_t dec_dw_part_floats(int G) {
2903	    return (int64_t)kDecDwMaxTiles * G * kDecDwTileFloats;
2904	}
2905	
2906	// Decode global dW work-item index gt → (spec index s, m_group, n_tile). Single-
2907	// source: m_group indexes M-atom GROUPS of kDecDwIL (group's first atom = m_group·
2908	// kDecDwIL, base row = m_group·kDecDwIL·64).
2909	template <int N>
2910	__device__ __forceinline__ void dectc_dw_decode(
2911	        const DecDwSpec spec[kDecNumDwSpecs], int gt, int& s, int& m_group, int& n_tile) {
2912	    int acc = 0;
2913	    for (s = 0; s < kDecNumDwSpecs; ++s) {
2914	        const int ng = dec_dw_groups(spec[s].Nout);
2915	        const int nt = (spec[s].Kin + N - 1) / N;
2916	        if (gt < acc + ng * nt) { int loc = gt - acc; m_group = loc / nt; n_tile = loc % nt; return; }
2917	        acc += ng * nt;
2918	    }
2919	    s = 4 * dec::kLayers; m_group = 0; n_tile = 0;   // unreachable (gt < n_dw); keep defined (head idx)
2920	}
2921	
2922	// PARTIAL dW for global tile gt over K-chunk kc of G → dw_part. K-chunk uses sp.K
2923	// (layer T / head B). FLOOR-BALANCED partition: chunk kc = [k0,k1) with
2924	// k0=floor(kc·KS/G), k1=floor((kc+1)·KS/G) — near-equal, summing to KS EXACTLY for
2925	// ANY KS≥G (no `G | KS` requirement → works at the production truncated B=4176,
2926	// where the head's KS=B/16 need NOT be divisible by G). A CEIL split would leave a
2927	// trailing EMPTY chunk whose slot stays unwritten → the reduce sums garbage (the
2928	// determinism-blind dW bug); floor never empties a chunk for KS≥G. Fresh ScaleD=0
2929	// per chunk → true partial. Writes the full 64×N tile (LOCAL rows) to the slot.
2930	template <int N>
2931	__device__ __forceinline__ void dectc_dw_run_tile_splitk(
2932	        const DecDwSpec spec[kDecNumDwSpecs], int gt, int kc, int G, float* __restrict__ dw_part,
2933	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
2934	    int s, m_group, n_tile;
2935	    dectc_dw_decode<N>(spec, gt, s, m_group, n_tile);
2936	    const DecDwSpec& sp = spec[s];
2937	    const int n_atoms = dec_dw_atoms(sp.Nout);
2938	    const int a0 = m_group * kDecDwIL;                      // first atom of the group
2939	    const int g_atoms = (n_atoms - a0) < kDecDwIL ? (n_atoms - a0) : kDecDwIL;
2940	    const int mbase = a0 * 64;
2941	    const int n0 = n_tile * N;
2942	    const int KS = sp.K / wgs::kWgmmaAtomK;                 // total k-atoms (T/16 or B/16)
2943	    const int k0 = (int)(((int64_t)kc       * KS) / G);     // floor-balanced chunk bounds
2944	    const int k1 = (int)(((int64_t)(kc + 1) * KS) / G);
2945	    const int kc_steps = k1 - k0;                          // sums to KS exactly over kc
2946	    // Slot holds the GROUP's kDecDwIL·64 rows (lr) × N cols (kDecDwTileFloats).
2947	    float* slot = dw_part + ((int64_t)gt * G + kc) * kDecDwTileFloats;
2948	    // Empty-chunk guard (KS<G, i.e. B<64): a k_steps=0 GEMM would emit the
2949	    // uninitialized accumulator → zero the WHOLE group slot + return instead of
2950	    // running it (the reduce sums all G slots unconditionally, so an empty chunk
2951	    // MUST be 0). Zero the full kDecDwIL·64·N slot (only g_atoms·64 rows are valid
2952	    // but the reduce reads only valid rows; zeroing all keeps it simple + safe).
2953	    if (kc_steps <= 0) {
2954	        for (int i = threadIdx.x; i < kDecDwTileFloats; i += blockDim.x) slot[i] = 0.0f;
2955	        __syncthreads();
2956	        return;
2957	    }
2958	    const int Nout = sp.Nout, Kin = sp.Kin;
2959	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
2960	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
2961	        return m < Nout ? dY[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Nout + m] : __float2bfloat16(0.f); };
2962	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
2963	        int nn = n0 + n; return nn < Kin ? X[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Kin + nn] : __float2bfloat16(0.f); };
2964	    // out(mbase+row, col, v): m is GLOBAL (srcA needs it; engine adds mbase0=mbase);
2965	    // the slot holds the GROUP's kDecDwIL·64 LOCAL rows → index by (m - mbase). The
2966	    // engine emits group-local rows in [0, g_atoms·64); writing them by (m-mbase)
2967	    // fills the lower g_atoms·64 rows (a ragged final group's tail rows stay as the
2968	    // zeroed/garbage upper rows but the reduce reads only valid rows → never used).
2969	    auto out  = [&] (int m, int n, float v) {
2970	        const int lr = m - mbase;
2971	        if (lr >= 0 && lr < kDecDwIL * 64 && n < N) slot[(int64_t)lr * N + n] = v; };
2972	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/kDecDwIL>(
2973	        mbase, g_atoms, /*n_real=*/N, kc_steps, srcA, srcB, out, sA, sB);
2974	}
