2976	// Deterministic reduce: output tile gt (% nCTA) sums its G chunk-partials ascending-kc
2977	// → grad. Same (gt → geometry) decode as the partial.
2978	template <int N>
2979	__device__ __forceinline__ void dectc_dw_reduce_splitk(
2980	        const DecDwSpec spec[kDecNumDwSpecs], int n_dw, int G, const float* __restrict__ dw_part,
2981	        float* __restrict__ grad, int cta, int nCTA) {
2982	    for (int gt = cta; gt < n_dw; gt += nCTA) {
2983	        int s, m_group, n_tile;
2984	        dectc_dw_decode<N>(spec, gt, s, m_group, n_tile);
2985	        const DecDwSpec& sp = spec[s];
2986	        const int mbase = m_group * kDecDwIL * 64;          // group's first global row
2987	        const int n0 = n_tile * N;
2988	        const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
2989	        // Valid group rows: up to kDecDwIL·64, clamped to the weight's row count.
2990	        const int grp_rows = kDecDwIL * 64;
2991	        const int Nrow = (sp.Nout - mbase) < grp_rows ? (sp.Nout - mbase) : grp_rows;
2992	        const int64_t base = (int64_t)gt * G * kDecDwTileFloats;
2993	        for (int idx = threadIdx.x; idx < Nrow * n_real; idx += blockDim.x) {
2994	            const int row = idx / n_real, col = idx % n_real;   // row = group-local lr
2995	            float accv = 0.0f;
2996	            for (int kc = 0; kc < G; ++kc)
2997	                accv += dw_part[base + (int64_t)kc * kDecDwTileFloats + (int64_t)row * N + col];
