3003	// Biases db = Σ_K dY  (column-sum of dY[K,Nout] → [Nout], per output row).
3004	//
3005	// WAS: each CTA strided ALL bias outputs and ran the full Σ_K reduction — i.e. the
3006	// ENTIRE column-sum was recomputed redundantly on ALL ~132 CTAs (the comment called
3007	// it "cheap" — true only when Nout≤3d=384 at the d=128 production width; at the
3008	// d=1024 roofline width Nout reaches 4d=4096 and K=T=65536, so the 132× redundant
3009	// reduction was the DOMINANT grad_asm cost — ~500 ms, eclipsing even the embedding
3010	// scan this task set out to fix; the per-phase profiler (ga.biases sub-timer) made
3011	// it visible). HBM traffic was 132 × Σ_s K_s·Nout_s·2 B ≈ 70 GB.
3012	//
3013	// NOW: SINGLE OWNER per output element across the WHOLE grid. Flatten the 9 specs'
3014	// outputs into one global index space [0, ΣNout) and grid-stride it over all CTAs
3015	// × threads, so each bias output is reduced EXACTLY ONCE and the work is spread
3016	// across the full grid. Traffic collapses to Σ_s K_s·Nout_s·2 B (one pass, ≈ 130×
3017	// less at d=1024). Reads stay COALESCED (consecutive threads → consecutive o on the
3018	// same k → consecutive dY addresses). DETERMINISM: one owner per output + the SAME

440	    // X + AX + AAX + orth (each maxNumel) + A (maxRows²) + nrm_partials(nCTA) + inv_norm(1)
441	    return (int64_t)4 * kVitMuonMaxNumel
442	         + (int64_t)kVitMuonMaxRows * kVitMuonMaxRows
443	         + nCTA + 1;
444	}
445	// ── LookSAM (STAGED in-kernel SAM 2nd backward) transient scratch — the ViT twin of
446	//    the decoder's dec_tc_looksam_floats (fused_decoder_megakernel.cuh). The SAM step
447	//    perturbs p in place, runs a SECOND fwd+bwd at p', and needs (a) a param BACKUP for
448	//    the exact restore (eager clones p before perturbing; an fp32 add is not bit-
449	//    reversible, so save — don't subtract back) + (b) a SEPARATE g_sam grad buffer so
450	//    the 2nd backward does NOT clobber the first grad `grad` (sam_dir = g_sam − grad
451	//    reads both). Both are total-sized + transient (NOT persistent state — sam_dir
452	//    itself persists in the `extra` state slice, bound by the cell). Carved
453	//    UNCONDITIONALLY (≈ 2·kVitTotalElems ≈ 3.3 MB) so the opt-agnostic launcher fits
454	//    every OptId; unused by every non-LookSAM cell (its P2.4 phase is if-constexpr'd
455	//    out → byte-identical). The ‖g‖ reduction reuses the loss workspace (sq_part/ron_bc,
456	//    as GrokAdamW's P2.5 / the decoder twin do), so no extra here. ──
457	__host__ __device__ __forceinline__ int64_t vit_tc_looksam_floats() {
458	    if (!kVitStagedOptScratch) return 0;      // bench (adamw-only): LookSAM never runs
459	    return (int64_t)2 * kVitTotalElems;       // [sam_backup | sam_grad]
460	}
461	// ── SuperGrok2 — the ViT twin of dec_tc_sg2_floats. Weights from HBM; the only SG2
462	//    workspace is the per-CTA meta-net scratch (sized for the largest tensor) + the
463	//    row_off64 staging prefix (kVitNumTensors int64 = 2*N floats — the adapter that
464	//    builds SG2State.row_off (const int64_t*) from __constant__ int kVitOffsets). ──
465	using VitSG2Dims = SG2Dims<>;
466	// max(kVitSizes), re-derived from the layout table (vit_layout.cuh) so the SAME SG2
467	// tail is correctly sized at ANY ladder width — was a d=128-pinned 65536.
468	constexpr int kVitSG2Nmax = kVitMaxTensorNumel;   // == vit_layout_check::max_size()
469	__host__ __device__ __forceinline__ int64_t vit_sg2_ws_stride_floats() {
470	    return (int64_t)2 * kVitNumTensors
471	         + sg2_ws_stride<VitSG2Dims>((int64_t)kVitSG2Nmax);
472	}
473	__host__ __device__ __forceinline__ int64_t vit_tc_sg2_floats(int nCTA) {
474	    if (!kVitStagedOptScratch) return 0;     // bench (adamw-only): SG2 never runs — and
475	        // its honestly-derived per-CTA stride (O(Nmax·d_model)) would OOM at large d.
476	    // +1 for the 8-byte realignment slack of sg2_ws_base (kVitTotalElems is odd).
477	    return (int64_t)nCTA * vit_sg2_ws_stride_floats() + 1;
478	}
479	__host__ __device__ __forceinline__ int64_t vit_tc_workspace_floats(int T, int B, int nCTA) {
480	    return vit_tc_acts_floats(T, B)
481	         + (int64_t)nCTA * vittc::vit_tile_scratch_total_f32()
482	         + (int64_t)nCTA * vittc::kLnVecElems
483	         + nCTA + 1
484	         + vit_tc_dw_part_floats()           // split-K dW partials (G>1)
485	         + vit_tc_opt_reduce_floats(nCTA)    // STAGED-opt (Prodigy) reduce slots
486	         + vit_tc_muon_floats(nCTA)          // STAGED-opt (Muon) NS per-matrix scratch
487	         + vit_tc_looksam_floats()           // STAGED-opt (LookSAM) SAM 2nd-bwd scratch
488	         + vit_tc_sg2_floats(nCTA);          // SuperGrok2 meta-net per-CTA scratch (carve-LAST)
489	}
