167	// The L3-REAL ViT megakernel needs the FLOAT patch path + a grad-partial
168	// workspace. Kept a SEPARATE kernel + launcher (not folded into the surrogate
169	// fused_megakernel) so the surrogate path is untouched.
170	//
171	// Workspace layout (one flat float buffer the host allocates + the kernel owns):
172	//   [0 .. nCTA*total)              : per-CTA grad partials (cta-major)
173	//   [nCTA*total .. nCTA*total+nCTA): per-CTA loss partials (NLL sum per slice)
174	//   [.. +1)                        : the reduced scalar loss (loss/B) the host reads
175	// total == kVitTotalElems == 418017.
176	struct ViTInputCtx {
177	    const float* patches;  // [B, kNPatch, kPatch] fp32 image patches
178	    const int*   targets;  // [B]                  int32 target ids in [0,kVocab)
179	    int          B;        // batch size
180	    float*       workspace; // grad partials + loss partials + reduced loss
181	    float*       loss_out;  // device float the kernel writes the mean loss into
182	};
