185	// ── The persistent megakernel (L3-REAL). gridDim.x = #SMs (one CTA/SM), 256
186	//    threads/CTA. VitSampleSmem (~183.67 KB) lives in DYNAMIC smem (extern). ────
187	//    GATED by SG_VIT_SCALAR_MEGAKERNEL (this fp32 path's VitSampleSmem grows with
188	//    SG_VIT_D and overflows the 227 KB dynamic-smem cap at the bench width; OFF lets
189	//    the TC path build at scaled d — see the flag note above). ────────────────────
190	// sizes/offsets are NOT host-passed: per-tensor numel/offset live in the
191	// __constant__ tables kVitSizes/kVitOffsets (vit_layout.cuh), read directly by
192	// the reduce + optimizer phases.
193	template <OptId Opt>
194	__global__ void __launch_bounds__(SG_TUNED_MEGA_BLOCK)
195	fused_vit_megakernel(PersistentContext ctx,
196	                     float* __restrict__ params,
197	                     ViTInputCtx in,
198	                     float* __restrict__ grad,        // reduced grad [total]
199	                     float lr, int step, FusedOptState st) {
200	    extern __shared__ char vit_smem_raw[];
201	    VitSampleSmem& sm = *reinterpret_cast<VitSampleSmem*>(vit_smem_raw);
202	    GridBarrier bar = ctx.barrier();
203	    const int cta = blockIdx.x;
204	    const int nCTA = (int)ctx.n_ctas;
205	    const int64_t total = kVitTotalElems;
206	    float* my_partial = in.workspace + (int64_t)cta * total;   // this CTA's dW
207	    float* loss_part = in.workspace + (int64_t)nCTA * total;   // [nCTA]
208	
209	    // §3.4 register repartition (producer WG gives back, consumer WG claims).
210	    const int wg = threadIdx.x / 128;
211	    if (wg == 0) ::sg::sm90::wgs::warpgroup_reg_dealloc<32>();
212	    else         ::sg::sm90::wgs::warpgroup_reg_alloc<200>();
213	
214	    // ── P0: zero this CTA's grad-partial slice + its loss slot. ───────────────
215	    for (int64_t i = threadIdx.x; i < total; i += blockDim.x) my_partial[i] = 0.0f;
216	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
217	    bar.sync();   // B0
218	
219	    // ── P1: batch-parallel fwd+bwd. Fixed contiguous slice [b0,b1) for this CTA.
220	    VitWeights w = vit_bind(params);
221	    VitGrad g = vit_bind_grad(my_partial);
222	    const int B = in.B;
223	    const int base = B / nCTA, rem = B % nCTA;
224	    const int b0 = cta * base + (cta < rem ? cta : rem);
225	    const int cnt = base + (cta < rem ? 1 : 0);
226	    const int b1 = b0 + cnt;
227	    __shared__ int tgt_s;
228	    float nll_acc = 0.0f;              // fp32 slice accumulator (thread-0 holds it)
229	    const int patch_elems = vit::kNPatch * vit::kPatch;   // 16*49 = 784
230	    for (int b = b0; b < b1; ++b) {
231	        // Load this sample's float patches into smem (cooperative).
232	        const float* src = in.patches + (int64_t)b * patch_elems;
233	        for (int i = threadIdx.x; i < patch_elems; i += blockDim.x)
234	            sm.patch[i / vit::kPatch][i % vit::kPatch] = src[i];
235	        if (threadIdx.x == 0) tgt_s = in.targets[b];
236	        __syncthreads();
237	        float nll = vit_forward_sample(w, tgt_s, &sm);
238	        vit_backward_sample(w, g, tgt_s, B, &sm);
239	        if (threadIdx.x == 0) nll_acc += nll;   // fixed-order fp32 sum within slice
240	        __syncthreads();   // sample boundary: all grad writes done before reuse
241	    }
242	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
243	    bar.sync();   // B1: all CTA partials + loss slots complete
244	
245	    // ── P2: deterministic cross-CTA reduce. Work-steal the param ELEMENT-RANGES
246	    //    (one task = one parameter tensor; sum its elements across CTAs in
247	    //    ascending CTA index). Summation ORDER (ascending cta) is fixed →
248	    //    deterministic regardless of which CTA grabs the task. ─────────────────
249	    {
250	        __shared__ int task_slot;
251	        TaskQueue q = ctx.queue();
252	        for (int t = q.next_block(&task_slot); t < kVitNumTensors;
253	             t = q.next_block(&task_slot)) {
254	            const int n = kVitSizes[t];
255	            const int64_t off = (int64_t)kVitOffsets[t];
256	            for (int i = threadIdx.x; i < n; i += blockDim.x) {
257	                float acc = 0.0f;
258	                for (int c = 0; c < nCTA; ++c)
259	                    acc += in.workspace[(int64_t)c * total + off + i];
260	                grad[off + i] = acc;
261	            }
262	        }
263	    }
264	    // Loss reduction (fp64 ordered) by CTA 0 only — the loss rel-tol is the
265	    // tightest gate; fp32 atomic-summing many terms can miss it.
266	    if (cta == 0 && threadIdx.x == 0) {
267	        double s = 0.0;
268	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
269	        float mean = (float)(s / (double)B);
270	        *in.loss_out = mean;
271	    }
272	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue for P3
273	
274	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 32
275	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
276	    st.lr = lr;
277	    {
278	        __shared__ int task_slot;
279	        TaskQueue q = ctx.queue();
280	        for (int t = q.next_block(&task_slot); t < kVitNumTensors;
281	             t = q.next_block(&task_slot)) {
282	            const int n = kVitSizes[t];
283	            const int64_t off = (int64_t)kVitOffsets[t];
284	            const FusedOptState ts = vit_rebase_state<Opt>(st, off);
285	            float* __restrict__ p = params + off;
286	            const float* __restrict__ gg = grad + off;
287	            for (int i = threadIdx.x; i < n; i += blockDim.x)
288	                apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
289	        }
290	    }
291	}
