293	// ── Host launcher — one persistent CTA per SM, 256 threads/CTA (2 warp-groups).
294	//    Mirrors launch_fused_decoder_megakernel's hang-freedom contract (occupancy≥1
295	//    or refuse), PLUS the DYNAMIC-SMEM opt-in that the ViT footprint requires:
296	//      (1) cudaFuncSetAttribute(MaxDynamicSharedMemorySize, sizeof(VitSampleSmem))
297	//      (2) dynamicSMemBytes = sizeof(VitSampleSmem) in the occ≥1 query
298	//      (3) dynamicSMemBytes = sizeof(VitSampleSmem) at <<<...>>>
299	//    All three are mandatory; missing any one makes the launch silently fail. ───
300	template <OptId Opt>
301	cudaError_t launch_fused_vit_megakernel(
302	        PersistentContext ctx, float* params, ViTInputCtx in,
303	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream) {
304	    int dev = 0;
305	    cudaError_t err = cudaGetDevice(&dev);
306	    if (err != cudaSuccess) return err;
307	    int n_sms = 0;
308	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
309	    if (err != cudaSuccess) return err;
310	
311	    const int dyn_smem = (int)sizeof(VitSampleSmem);   // ≈ 188080 B (183.67 KB)
312	
313	    // (1) Opt in to >48 KB dynamic smem for THIS kernel. Without this the launch
314	    //     fails with cudaErrorInvalidValue (the static 48 KB default applies).
315	    err = cudaFuncSetAttribute(
316	        (const void*)&fused_vit_megakernel<Opt>,
317	        cudaFuncAttributeMaxDynamicSharedMemorySize, dyn_smem);
318	    if (err != cudaSuccess) return err;
319	
320	    // (2) Occupancy with the REAL dynamic-smem request (hang-freedom is honest).
321	    int occ = 0;
322	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
323	        &occ, (const void*)&fused_vit_megakernel<Opt>, SG_TUNED_MEGA_BLOCK,
324	        /*dynamicSMemBytes=*/dyn_smem);
325	    if (err != cudaSuccess) return err;
326	    // At least one CTA per SM must be resident or the grid barrier can never be
327	    // satisfied. ~183.67 KB dynamic smem fits the sm_90 227 KB cap at occ=1 (the
328	    // persistent megakernel is one-CTA-per-SM by design); if it cannot place one
329	    // block/SM, REFUSE rather than hang.
330	    assert(occ >= 1 &&
331	           "fused_vit_megakernel: 0 blocks/SM — GridBarrier would hang. The ViT "
332	           "per-sample smem (~184KB dynamic) + regs exceed one-block-per-SM "
333	           "occupancy on this device; reduce footprint or fall back to eager.");
334	    if (occ < 1) return cudaErrorLaunchOutOfResources;
335	
336	    const unsigned launch_ctas = (unsigned)n_sms;
337	    ctx.n_ctas = launch_ctas;
338	
339	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
340	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
341	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
