319	    TORCH_CHECK(params.is_cuda() && params.scalar_type() == torch::kFloat32 && params.is_contiguous());
320	    TORCH_CHECK(params.numel() == kVitTotalElems, "params must be the flat ViT blob (", kVitTotalElems, ")");
321	    TORCH_CHECK(patches.is_cuda() && patches.scalar_type() == torch::kFloat32 && patches.is_contiguous());
322	    TORCH_CHECK(targets.is_cuda() && targets.scalar_type() == torch::kInt32 && targets.is_contiguous());
323	    const int B = (int)targets.numel();
324	    TORCH_CHECK(patches.numel() == (int64_t)B * vit::kNPatch * vit::kPatch, "patches must be [B, kNPatch, kPatch]");
325	    const int64_t total = kVitTotalElems;
326	    TORCH_CHECK(state.is_cuda() && state.scalar_type() == torch::kFloat32 && state.is_contiguous()
327	                && state.numel() >= 3 * total, "state must be contiguous fp32 [>=3*total]");
328	
329	    int dev = params.get_device();
330	    int n_sms = 1;
331	    cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
332	
333	    static torch::Tensor s_gn, s_ga, s_gg, s_ws;
334	    static int64_t s_ws_floats = 0;
335	    const int64_t need = (int64_t)n_sms * total + n_sms + 1;
336	    if (!s_gn.defined()) {
337	        auto oi = torch::dtype(torch::kInt32).device(params.device());
338	        s_gn = torch::zeros({1}, oi); s_ga = torch::zeros({1}, oi); s_gg = torch::zeros({1}, oi);
339	    }
340	    if (s_ws_floats < need) {
341	        s_ws = torch::empty({need}, torch::dtype(torch::kFloat32).device(params.device()));
342	        s_ws_floats = need;
343	    }
344	    auto grad = torch::zeros({total}, torch::dtype(torch::kFloat32).device(params.device()));
345	    float* loss_out = s_ws.data_ptr<float>() + (int64_t)n_sms * total + n_sms;
346	
347	    PersistentContext ctx{
348	        s_gn.data_ptr<int>(),
349	        reinterpret_cast<unsigned*>(s_ga.data_ptr<int>()),
350	        reinterpret_cast<unsigned*>(s_gg.data_ptr<int>()),
351	        kVitNumTensors, 0u};
352	
353	    FusedOptState st;
354	    float* m = state.data_ptr<float>();
355	    st.exp_avg = m; st.exp_avg_sq = m + total;
356	    st.lr = (float)lr; st.beta1 = (float)beta1; st.beta2 = (float)beta2;
357	    st.eps = (float)eps; st.wd = (float)weight_decay;
358	    st.bc1 = (float)bc1; st.bc2 = (float)bc2;
359	
360	    ViTInputCtx in;
361	    in.patches = patches.data_ptr<float>();
362	    in.targets = targets.data_ptr<int>();
363	    in.B = B;
364	    in.workspace = s_ws.data_ptr<float>();
365	    in.loss_out = loss_out;
366	
367	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
368	    cudaError_t err = ::sg::fused::sm90::launch_fused_vit_megakernel<OptId::AdamW>(
369	        ctx, params.data_ptr<float>(), in, grad.data_ptr<float>(),
370	        (float)lr, (int)step, st, stream);
371	    TORCH_CHECK(err == cudaSuccess, "scalar megakernel launch failed: ", cudaGetErrorString(err));
372	    C10_CUDA_CHECK(cudaStreamSynchronize(stream));
373	
374	    auto loss_cpu = s_ws.slice(0, (int64_t)n_sms * total + n_sms, (int64_t)n_sms * total + n_sms + 1)
375	                        .to(torch::kCPU);
376	    return {loss_cpu, grad};
377	}
