300	//  by vit_acts_bind. The struct holds base pointers per region.
301	//
302	//  ViT ADDS X_patch (the float→bf16 patch input the patch_proj dW reads) and
303	//  REPLACES the decoder's tok/pos embedding adjoint plumbing with dh0 (the
304	//  post-cat, pre-pos grad) whose CLS rows feed cls_token and whose patch rows
305	//  feed patch_proj; pos is Σ over all rows by position.
306	// ════════════════════════════════════════════════════════════════════════
307	struct VitActs {
308	    // Patch-proj input (the image patches as bf16, laid out as PATCH token rows
309	    // [Tp, kPatch] where Tp = nsamp*kNPatch — patch_proj dW = dh0_patch^T @ this):
310	    __nv_bfloat16* X_patch;               // [Tp, kPatch]
311	    // Per-layer linear INPUTS X (needed by dW = dY^T @ X):
312	    __nv_bfloat16* X_in[vit::kLayers];    // [T, d]    in_proj input (= layer input)
313	    __nv_bfloat16* X_ctx[vit::kLayers];   // [T, d]    out_proj input (attn context)
314	    __nv_bfloat16* X_x1[vit::kLayers];    // [T, d]    ff0 input (n1 output)
315	    __nv_bfloat16* X_gact[vit::kLayers];  // [T, dff]  ff2 input (gelu output)
316	    // Per-layer linear OUTPUT adjoints dY (needed by dW + bias db = Σ_t dY):
317	    __nv_bfloat16* dY_qkv[vit::kLayers];  // [T, 3d]   in_proj output adjoint
318	    __nv_bfloat16* dY_a[vit::kLayers];    // [T, d]    out_proj output adjoint
319	    __nv_bfloat16* dY_ff0[vit::kLayers];  // [T, dff]  ff0 output adjoint
320	    __nv_bfloat16* dY_ff2[vit::kLayers];  // [T, d]    ff2 output adjoint
321	    // Head (B rows — CLS position only):
322	    __nv_bfloat16* X_hn;                  // [B, d]    head input
323	    __nv_bfloat16* dY_logits;             // [B, V]    head output adjoint (dlogits)
324	    // Embedding-input adjoint (post-cat, pre-pos): cls/patch/pos owners read it:
325	    __nv_bfloat16* dh0;                   // [T, d]
326	};
327	
328	__device__ __forceinline__ VitActs vit_acts_bind(__nv_bfloat16* p, int T, int B) {
329	    VitActs a;
330	    int64_t off = 0;
331	    const int Tp = (T / vit::kSeq) * vit::kNPatch;
332	    const int64_t Td = (int64_t)T * vit::kD;
333	    const int64_t T3d = (int64_t)T * 3 * vit::kD;
334	    const int64_t Tff = (int64_t)T * vit::kDff;
335	    a.X_patch = p + off; off += (int64_t)Tp * vit::kPatch;
336	    for (int li = 0; li < vit::kLayers; ++li) {
337	        a.X_in[li]   = p + off; off += Td;
338	        a.X_ctx[li]  = p + off; off += Td;
339	        a.X_x1[li]   = p + off; off += Td;
340	        a.X_gact[li] = p + off; off += Tff;
341	        a.dY_qkv[li] = p + off; off += T3d;
342	        a.dY_a[li]   = p + off; off += Td;
343	        a.dY_ff0[li] = p + off; off += Tff;
344	        a.dY_ff2[li] = p + off; off += Td;
345	    }
346	    a.X_hn      = p + off; off += (int64_t)B * vit::kD;
347	    a.dY_logits = p + off; off += (int64_t)B * vit::kVocab;
348	    a.dh0       = p + off; off += Td;
349	    return a;
350	}
