353	__host__ __device__ __forceinline__ int64_t vit_acts_bf16_count(int T, int B) {
354	    const int64_t d = vit::kD, dff = vit::kDff, V = vit::kVocab, L = vit::kLayers;
355	    const int Tp = (T / vit::kSeq) * vit::kNPatch;
356	    const int64_t Td = (int64_t)T * d, T3d = (int64_t)T * 3 * d, Tff = (int64_t)T * dff;
357	    int64_t bf = (int64_t)Tp * vit::kPatch;                // X_patch
358	    for (int li = 0; li < L; ++li) bf += Td + Td + Td + Tff + T3d + Td + Tff + Td;
359	    bf += (int64_t)B * d + (int64_t)B * V + Td;            // X_hn + dY_logits + dh0
360	    return bf;
361	}
